404	+        events.extend(text_block(1, "A"));
405	+        events.extend(tool_block(2, "tu_x"));
406	+        events.extend(thinking_block(3, "SIG_FAKE_2"));
407	+        events.extend(text_block(4, "B"));
408	+        events.extend(tool_block(5, "tu_y"));
409	+        events.push(AnthropicEvent::MessageStop);
410	+        let items = items_of(&translate_events(events));
411	+        let body = turn2_body(&items);
412	+        let content = assistant_content(&body);
413	+        let blocks = content.as_array().unwrap();
414	+        let shape: Vec<(String, String)> = blocks
415	+            .iter()
416	+            .map(|b| {
417	+                let kind = b["type"].as_str().unwrap().to_owned();
418	+                let key = match kind.as_str() {
419	+                    "thinking" => b["signature"].as_str().unwrap().to_owned(),
420	+                    "text" => b["text"].as_str().unwrap().to_owned(),
421	+                    _ => b["id"].as_str().unwrap().to_owned(),
422	+                };
423	+                (kind, key)
