439	+    /// Record a user turn and the items through a session, then project.
440	+    fn session_messages(items: &[Item]) -> Vec<Item> {
441	+        let mut recorder = SessionRecorder::new("root");
442	+        recorder.record_input(&[user_q()]);
443	+        for item in items {
444	+            match item {
445	+                Item::AssistantMessage { .. } => {
446	+                    recorder.observe(&AgentEvent::MessageOutput { item: item.clone() })
447	+                }
448	+                Item::ToolCall { .. } => {
449	+                    recorder.observe(&AgentEvent::ToolCallItem { item: item.clone() })
450	+                }
451	+                _ => {}
452	+            }
453	+        }
454	+        for result in results_for(items) {
455	+            recorder.observe(&AgentEvent::ToolOutputItem { item: result });
456	+        }
457	+        paigasus_helikon_core::project(&recorder.drain()).messages
458	+    }
459	+
460	+    #[test]
461	+    fn session_projection_round_trip() {
462	+        for fixture in [
463	+            include_str!("../../tests/fixtures/thinking_text_tool_use.txt"),
464	+            include_str!("../../tests/fixtures/interleaved_thinking.txt"),
465	+        ] {
466	+            let (items, _) = turn_items(fixture);
467	+            let direct = assistant_content(&turn2_body(&items));
468	+            assert!(
469	+                direct
470	+                    .as_array()
471	+                    .unwrap()
472	+                    .iter()
473	+                    .any(|b| b["type"] == "thinking"),
474	+                "direct body must carry thinking: {direct}"
475	+            );
476	+            let projected = body_of(session_messages(&items));
477	+            assert_eq!(assistant_content(&projected), direct, "{projected}");
478	+        }
479	+    }
480	+}
